const test = require('node:test');
const assert = require('node:assert/strict');
const { formatMoney } = require('./money');

test('dollars and cents', () => {
  assert.equal(formatMoney(123456), '$1,234.56');
  assert.equal(formatMoney(5), '$0.05');
  assert.equal(formatMoney(-5), '-$0.05');
  assert.equal(formatMoney(0), '$0.00');
  assert.equal(formatMoney(123456789), '$1,234,567.89');
});

test('other currencies', () => {
  assert.equal(formatMoney(1999, 'EUR'), '€19.99');
  assert.equal(formatMoney(1234567, 'JPY'), '¥1,234,567');
  assert.equal(formatMoney(12345, 'GBP'), '£123.45');
});

test('validation and edge cases', () => {
  assert.throws(() => formatMoney(1.23), RangeError);
  assert.throws(() => formatMoney('123'), RangeError);
  assert.throws(() => formatMoney(123, 'XYZ'), RangeError);
  assert.throws(() => formatMoney(123, 'toString'), RangeError);
  assert.throws(() => formatMoney(Number.MAX_SAFE_INTEGER + 1), RangeError);
});
"}
